#!/bin/bash
# Wait for the N1.5 finetune to exit, then run the whole deliverable pipeline on GPU4:
#   predict (full 1397, batch_size=1, seed 0)  ->  sampling-variance footnote (200x5)  ->  score
#
# Chained on purpose: GPU4 is contended (OFT is queued behind me), so the card should not
# sit idle waiting for a human to notice training finished.
#
# Waits on an exact PID (kill -0), not a pgrep pattern -- pattern matching against the
# process table gives false positives in this harness.
#
# bash reads a running script by byte offset: do NOT edit this file while it is executing.
set -uo pipefail
: "${NERO_ROOT:?please 'source env.sh' first (see env.example.sh at the repo root)}"

TRAIN_PID="${1:?trainer pid}"
GPU="${2:-4}"
BENCH="$NERO_ROOT/bench"
OUT_ROOT="${NERO_CKPT:-$NERO_ROOT/checkpoints}/gr00t_n15_nero_b2"
PY="$NERO_ROOT/third_party/Isaac-GR00T-n1d5/.venv/bin/python"
SUBSET=$BENCH/logs/variance_subset200.npy

log() { echo "[$(date '+%F %T')] $*"; }

log "waiting for N1.5 trainer PID $TRAIN_PID to exit..."
while kill -0 "$TRAIN_PID" 2>/dev/null; do sleep 30; done
log "trainer gone; letting the final safetensors write settle"
sleep 30

# prefer the explicit step-10000 checkpoint for provenance; fall back to the top-level
# final save that runner.train() writes via safe_save_model_for_hf_trainer().
MODEL=""
for cand in "$OUT_ROOT/checkpoint-10000" "$OUT_ROOT"; do
  if [ -f "$cand/model.safetensors.index.json" ]; then MODEL="$cand"; break; fi
done
if [ -z "$MODEL" ]; then
  log "ABORT: no finished model found. present: $(ls "$OUT_ROOT" | tr '\n' ' ')"
  log "last progress: $(tr '\r' '\n' < "$BENCH/logs/train_gr00t_n15.log" | grep -oE '[0-9]+/10000' | tail -1)"
  exit 1
fi
log "model = $MODEL"
log "disk: $(df -h /home2 | tail -1)"

mkdir -p "$BENCH/logs/variance"

# ---- 1. the deliverable: all 1397 anchors, fixed seed, batch_size=1 --------------
# batch_size=1 is deliberate: bf16 matmul is not batch-invariant, so a row's value
# depends on the batch shape it was computed in. Pinning B=1 is what makes the
# 200-anchor variance rows bit-identical to the corresponding full-run rows.
log "=== predict: full 1397 anchors, seed 0, batch_size=1 ==="
CUDA_VISIBLE_DEVICES=$GPU PYTHONPATH=$BENCH/configs $PY "$BENCH/scripts/predict/predict_gr00t.py" \
  --model-path "$MODEL" --batch-size 1 --seed 0 \
  --out "$BENCH/preds/preds_gr00t_n15.npz" 2>&1
RC=$?
log "predict rc=$RC"
[ $RC -eq 0 ] || { log "ABORT: predict failed"; exit 1; }

# ---- 2. sampling-variance footnote (NOT a leaderboard artifact) ------------------
# shared subset, loaded never regenerated; results go to logs/variance/, not preds/.
log "=== variance footnote: shared 200 anchors x 5 noise draws, batch_size=1 ==="
CUDA_VISIBLE_DEVICES=$GPU PYTHONPATH=$BENCH/configs $PY "$BENCH/scripts/predict/predict_gr00t.py" \
  --model-path "$MODEL" --batch-size 1 --seed 0 --repeats 5 \
  --subset "$SUBSET" \
  --var-out "$BENCH/logs/variance/var_gr00t_n15_200x5.npz" \
  --out "$BENCH/logs/variance/preds_gr00t_n15_subset200_seed0.npz" 2>&1
VRC=$?
log "variance rc=$VRC"
[ $VRC -eq 0 ] || { log "ABORT: variance failed"; exit 1; }

# ---- 2b. prove the R draws were NON-ALIASING (CPU, ~2s, no model) -----------------
# Upstream evidence for the footnote: std==0 and bit_exact_across_draws are BOTH computed
# from the same R arrays, so neither can tell "deterministic decoder" from "the harness
# reused a seed". This executes the shipped PinnedNoise over the real anchor indices and
# counts duplicate noise tensors — and carries a power control that must trip. Deriving
# the same claim from the source constant does NOT work: n17's leg had the correct prime
# stride in the formula while the driver never passed `repeat` (effective stride 1,
# 254/1000 tensors aliased) and a constant-derived field still reported it clean.
log "=== seed-collision check (non-aliasing draws, + power control) ==="
$PY "$BENCH/archive/n15_seed_collision_check.py" 2>&1
SEEDRC=$?
log "seed-collision rc=$SEEDRC"
[ $SEEDRC -eq 0 ] || { log "ABORT: draws alias — the sampling std would be biased LOW"; exit 1; }

# ---- 2c. footnote json (refuses to write without 2b) ------------------------------
log "=== variance footnote json ==="
python3 "$BENCH/archive/n15_variance_json.py" 2>&1
JRC=$?
log "variance-json rc=$JRC"
[ $JRC -eq 0 ] || { log "ABORT: footnote json failed"; exit 1; }

# ---- 3. score ---------------------------------------------------------------------
log "=== score.py ==="
$PY "$BENCH/scripts/score/score.py" 2>&1
SRC=$?
log "score rc=$SRC"
# score.py only RENDERS the board (read-only), so a failure must not abort the run and
# lose the artifacts already on disk — but it must not be invisible either.
[ $SRC -eq 0 ] || log "WARNING: score.py failed (rc=$SRC) — preds/variance are on disk, board not rendered"

# NOT a release signal. This line is printed by a process that is still alive and
# still owns the CUDA context, so it cannot certify "process exited" — the release
# needs preds+variance on disk AND this pid gone AND nvidia-smi -i $GPU empty, and
# only a human/agent observing all three afterwards can assert it.
# Every rc quoted below is a variable this script actually captured. A log line must
# never restate a status it did not read: the previous version hardcoded "(rc=0)"
# while score.py's rc was never captured, so a score.py crash printed a line claiming
# success — the same defect as the old "GPU is FREE" line, one layer down and better
# camouflaged, because it sat inside the *fixed* version. (openvla-oft 2026-08-05.)
log "=== compute stages finished (predict rc=$RC variance rc=$VRC score rc=$SRC). This pid still holds GPU$GPU until exit. ==="
log "disk: $(df -h /home2 | tail -1)"
log "ckpt dirs: $(ls -d $OUT_ROOT/checkpoint-* 2>/dev/null | tr '\n' ' ')"
nvidia-smi --query-gpu=index,memory.used --format=csv,noheader | sed -n "$((GPU+1))p"
